import React, { useState } from 'react';
import { PostCreateStep } from './types';

interface Props {
  steps: PostCreateStep[];
  projectPath: string;
}

/**
 * Final wizard step: the commands the user still has to run after scaffolding.
 * Flutter is the driving case — its `android/`/`ios/` runners are generated by
 * the SDK, so the scaffold alone is not runnable. Surfacing them here (instead
 * of a warning toast that vanishes) keeps the project in a known state.
 */
export const StepNextSteps: React.FC<Props> = ({ steps, projectPath }) => {
  const [copied, setCopied] = useState<number | null>(null);

  const copy = async (command: string, index: number) => {
    try {
      await navigator.clipboard.writeText(command);
      setCopied(index);
      window.setTimeout(() => setCopied((current) => (current === index ? null : current)), 1500);
    } catch {
      // Clipboard is unavailable in some embedded contexts; the command stays
      // selectable in the code block either way.
    }
  };

  return (
    <div>
      <h3 className="wizard-step-title">Next steps</h3>
      <p className="wizard-step-desc">
        The project was created at <code>{projectPath}</code>. Run the following once, from the project
        root, before starting the app:
      </p>
      {steps.map((step, index) => (
        <div className="wizard-next-step" key={`${index}-${step.label}`}>
          <div className="wizard-next-step-head">
            <span className="wizard-next-step-num">{index + 1}</span>
            <span className="wizard-next-step-label">{step.label}</span>
          </div>
          {step.detail && <p className="wizard-next-step-detail">{step.detail}</p>}
          {step.command && (
            <div className="wizard-next-step-command">
              <code>{step.command}</code>
              <button
                type="button"
                className="wizard-btn wizard-btn-secondary wizard-copy-btn"
                onClick={() => copy(step.command as string, index)}
              >
                {copied === index ? 'Copied' : 'Copy'}
              </button>
            </div>
          )}
        </div>
      ))}
    </div>
  );
};
